package com.example.lifecycle;

import org.springframework.beans.BeansException;
import org.springframework.beans.factory.BeanNameAware;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationContextAware;
import org.springframework.stereotype.Component;

import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;

@Component
public class DatabaseConnectionPoolManager implements BeanNameAware, ApplicationContextAware, BeanPostProcessor {

    private String beanName;
    private ApplicationContext applicationContext;

    @Override
    public void setBeanName(String name) {
        this.beanName = name;
        System.out.println("1. Aware Phase: BeanNameAware -> " + name);
    }

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
        this.applicationContext = applicationContext;
        System.out.println("2. Aware Phase: ApplicationContextAware injected.");
    }

    @Override
    public Object postProcessBeforeInitialization(Object bean, String beanName) throws BeansException {
        if (bean == this) {
            System.out.println("3. BeanPostProcessor: postProcessBeforeInitialization for " + beanName);
        }
        return bean;
    }

    @PostConstruct
    public void init() {
        System.out.println("4. Initialization: @PostConstruct executed for pool manager.");
    }

    @Override
    public Object postProcessAfterInitialization(Object bean, String beanName) throws BeansException {
        if (bean == this) {
            System.out.println("5. BeanPostProcessor: postProcessAfterInitialization (Ready state approaches).");
        }
        return bean;
    }

    @PreDestroy
    public void cleanup() {
        System.out.println("6. Destruction: @PreDestroy executed. Closing connections.");
    }
}
